self.KB_CONTENT["card:779932"]={"id":"card:779932","ty":"card","sourceId":"779932","title":"『生產入庫單憑證(IDL)』中的『選擇生產入庫單號 (TF002)』為何？","ver":"GP4以上","topic":"入庫單","keywords":["入庫單","憑證","單號","生產"],"y":"other","answer":"* 空白表全部。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
