self.KB_CONTENT["card:783689"]={"id":"card:783689","ty":"card","sourceId":"783689","title":"『付款單產生預約付款作業』中的『輸入預計收支起始代號』為何？","ver":"GP4以上","topic":"付款單","keywords":["付款單","編號","預計"],"y":"other","answer":"* 不可空白。* 即產生的預計收支資料是由輸入的預計收支起始代號開始編號。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
