self.KB_CONTENT["field:782376"]={"id":"field:782376","ty":"field","sourceId":"782376","title":"選擇部門代號","ver":"GP4以上","topic":"","keywords":[],"job":"應收票據票況表","code":"TC015","answer":"* 可自行選擇離散或區間。* 可複選(icon)或按[F2]部門資料查詢，空白表全部。進階選項","file":"fields.jsonl"};
